import java.util.*;

class RandomizedCollection {
  private final Map<Integer, Set<Integer>> positions = new HashMap<>();
  private final List<Integer> values = new ArrayList<>();
  private final Random random = new Random();

  public RandomizedCollection() {}

  public boolean insert(int val) {
    Set<Integer> pos = positions.computeIfAbsent(val, k -> new HashSet<>());
    pos.add(values.size());
    values.add(val);
    return pos.size() == 1;
  }

  public boolean remove(int val) {
    Set<Integer> pos = positions.get(val);
    if (pos == null || pos.isEmpty()) return false;
    int i = pos.iterator().next();
    pos.remove(i);
    int lastIndex = values.size() - 1, last = values.get(lastIndex);
    if (i != lastIndex) {
      // move the last value into the hole
      values.set(i, last);
      Set<Integer> lastPos = positions.get(last);
      lastPos.remove(lastIndex);
      lastPos.add(i);
    }
    values.remove(lastIndex);
    return true;
  }

  public int getRandom() {
    return values.get(random.nextInt(values.size()));
  }
}
